    '.wsh-ssh-connection:hover{background:var(--ssh-hover)}.wsh-ssh-connection[data-selected=true]{background:var(--ssh-hover);border-color:var(--ssh-border-strong);box-shadow:inset 3px 0 var(--ssh-primary)}',
