    '.wsh-ssh-connection-select{display:flex;align-items:center;gap:8px;flex:1;min-width:0;border:0;background:transparent;color:inherit;font:inherit;text-align:left;padding:2px;border-radius:var(--dsw-radius-xs);cursor:pointer}',
    '.wsh-ssh-connection-text{display:grid;min-width:0;gap:2px}.wsh-ssh-connection-text strong{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
