    '.wsh-ssh-dot{width:8px;height:8px;border-radius:50%;flex:none;background:var(--ssh-idle)}.wsh-ssh-dot[data-state=connected]{background:var(--ssh-success)}',
    '.wsh-ssh-switch{appearance:none;-webkit-appearance:none;width:32px;height:18px;border-radius:999px;border:1px solid var(--ssh-border-strong);background:var(--dsw-alias-fill-l1);position:relative;flex:none;cursor:pointer;transition:background .15s ease}',
    '.wsh-ssh-switch:before{content:"";position:absolute;top:2px;left:2px;width:12px;height:12px;border-radius:50%;background:var(--dsw-alias-switch-thumb);box-shadow:var(--dsw-shadow-lv1);transition:transform .15s ease}',
    '.wsh-ssh-switch:checked{background:var(--ssh-primary)}.wsh-ssh-switch:checked:before{transform:translateX(14px)}.wsh-ssh-switch:disabled{opacity:.5;cursor:not-allowed}',
    '.wsh-ssh-more{border:1px solid transparent;background:transparent;color:inherit;font:inherit;font-size:15px;line-height:1;padding:2px 7px;border-radius:var(--dsw-radius-xs);cursor:pointer}.wsh-ssh-more:hover:not(:disabled){background:var(--ssh-hover)}.wsh-ssh-more:disabled{opacity:.5;cursor:not-allowed}',
    '.wsh-ssh-menu{position:absolute;right:8px;top:calc(100% - 2px);z-index:5;min-width:180px;display:grid;padding:4px;border:1px solid var(--ssh-border-strong);border-radius:var(--dsw-radius-md);background:var(--dsw-alias-bg-overlay);box-shadow:var(--dsw-shadow-lv2)}',
    '.wsh-ssh-menu button{border:0;background:transparent;color:inherit;font:inherit;font-size:12px;text-align:left;padding:7px 9px;border-radius:var(--dsw-radius-xs);cursor:pointer}.wsh-ssh-menu button:hover:not(:disabled){background:var(--ssh-hover)}.wsh-ssh-menu button:disabled{opacity:.5;cursor:not-allowed}.wsh-ssh-menu-danger{color:var(--ssh-error)}',
    '.wsh-ssh-detail{min-width:0;padding:16px 18px;display:grid;gap:14px;align-content:start}',
    '.wsh-ssh-detail-header{display:grid;gap:10px;min-width:0}',
    '.wsh-ssh-detail-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;flex-wrap:wrap}',
    '.wsh-ssh-detail-title{display:grid;gap:4px;min-width:0}.wsh-ssh-detail-title code{color:var(--ssh-muted)}',
